    private Iconos() {
    }

    // Crea un icono del tamaño dado (en píxeles) con la forma indicada.
    public static Region crear(String forma, double tamano) {
        Region r = new Region();
        r.getStyleClass().add("icono");
        r.setStyle("-fx-shape: \"" + forma + "\";");
        r.setMinSize(tamano, tamano);
        r.setPrefSize(tamano, tamano);
        r.setMaxSize(tamano, tamano);
        return r;
    }
